mapper.update:
UPDATE workflow_draft
SET validation_state = 'VALID', validation_digest = #{digest}, validated_at = #{now},
    lock_version = lock_version + 1, updated_at = #{now},
    updated_by_type = 'USER', updated_by_id = #{actorId}
WHERE tenant_id = #{tenantId} AND draft_id = #{draftId} AND status = 'EDITABLE'
  AND lock_version = #{expectedVersion}

UPDATE workflow_draft
SET validation_state = 'UNVALIDATED', validation_digest = NULL,
    validated_at = NULL, lock_version = lock_version + 1,
    updated_at = #{now}, updated_by_type = 'USER', updated_by_id = #{actorId}
WHERE tenant_id = #{tenantId} AND draft_id = #{draftId} AND status = 'EDITABLE'
  AND lock_version = #{expectedVersion}

UPDATE workflow_draft
SET status = 'CONSUMED', consumed_at = #{now}, lock_version = lock_version + 1,
    updated_at = #{now}, updated_by_type = 'USER', updated_by_id = #{actorId}
WHERE tenant_id = #{tenantId} AND draft_id = #{draftId} AND status = 'EDITABLE'
  AND validation_state = 'VALID' AND lock_version = #{expectedVersion}

